{
  "schema_version": "agentto.spec/v0",
  "name": "Gearbox output bracket",
  "description": "End-mounted steel bracket carrying a 40 N*m torque about x through two drive lugs; y is height and z is depth.",
  "units": {
    "length": "mm",
    "force": "N"
  },
  "domain": {
    "kind": "box",
    "size": [160, 80, 80]
  },
  "material": {
    "name": "steel",
    "E": 210000,
    "nu": 0.3
  },
  "volume_fraction": 0.3,
  "supports": [
    {
      "id": "gearbox_mount",
      "region": {
        "kind": "face",
        "face": "x-"
      },
      "fix": ["x", "y", "z"]
    }
  ],
  "loads": [
    {
      "id": "top_drive_lug",
      "region": {
        "kind": "patch",
        "face": "x+",
        "center": [72, 40],
        "size": [16, 16]
      },
      "force": [0, 0, 625],
      "distribution": "uniform_nodes"
    },
    {
      "id": "bottom_drive_lug",
      "region": {
        "kind": "patch",
        "face": "x+",
        "center": [8, 40],
        "size": [16, 16]
      },
      "force": [0, 0, -625],
      "distribution": "uniform_nodes"
    }
  ],
  "resolution": {
    "h": 2
  },
  "meta": {
    "torque_direction_assumption": "+x by the right-hand rule",
    "lug_placement": "Patches lie flush with the top and bottom edges and are centered in depth.",
    "torque_calculation": "625 N times 64 mm between lug centers equals 40000 N*mm, or 40 N*m."
  }
}
